// A ShaderLayer: one `inout material`, named after the 1.x output.
/// @name Layers/ML_LpTint
/// @layer
export void ML_LpTint(inout material Attrs)
{
    material Base = Attrs;
    Attrs = UE.Expression(Class = "MakeMaterialAttributes");
    Attrs.BaseColor = Base.BaseColor * float3(1.0, 0.5, 0.25);
}
